function isMobile(){return window.matchMedia(`(max-width:${MOBILE_BREAKPOINT}px)`).matches}
function ensureStyles(){if(document.getElementById("wan-mobile-ui-styles"))return;const s=document.createElement("style");s.id="wan-mobile-ui-styles";s.setAttribute("data-persist","true");s.textContent=CSS;document.head.appendChild(s)}
function safeRead(key){try{const raw=localStorage.getItem(key);if(!raw)return null;const data=JSON.parse(raw);if(!data||typeof data.updatedAt!=="number"||Date.now()-data.updatedAt>STATE_TTL_MS){localStorage.removeItem(key);return null}data.updatedAt=Date.now();localStorage.setItem(key,JSON.stringify(data));return data}catch{return null}}
function safeWrite(key,value){try{localStorage.setItem(key,JSON.stringify({...value,updatedAt:Date.now()}))}catch{}}

function currentTitle(){const slug=document.body?.dataset?.slug||"index";if(slug==="index")return"Wan";const t=document.querySelector(".center .article-title")?.textContent?.trim();if(t)return t;if(slug.startsWith("tags/")){try{return decodeURIComponent(slug.slice(5))||"Tags"}catch{return slug.slice(5)||"Tags"}}const last=slug.split("/").filter(Boolean).pop()||"Wan";try{return decodeURIComponent(last)}catch{return last}}
function ensureHeader(){let h=document.querySelector(".wan-mobile-header");if(!h){h=document.createElement("header");h.className="wan-mobile-header";h.innerHTML='<button type="button" class="wan-mobile-header-button wan-mobile-left-button" aria-label="Open list drawer" aria-expanded="false"><svg viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"></path></svg></button><button type="button" class="wan-mobile-header-title" aria-label="Scroll to top"></button><button type="button" class="wan-mobile-header-button wan-mobile-right-button" aria-label="Open page drawer" aria-expanded="false"><svg viewBox="0 0 24 24"><path d="M5 5h14v14H5zM14 5v14M8 9h3M8 12h3M8 15h3"></path></svg></button>';document.body.prepend(h)}const t=h.querySelector(".wan-mobile-header-title");if(t){t.textContent=currentTitle();t.title=currentTitle()}}
function drawer(side){return document.querySelector(side==="left"?".page > #quartz-body > .sidebar.left":".page > #quartz-body > .sidebar.right")}
function ensureOverlay(){let o=document.querySelector(".wan-drawer-overlay");if(!o){o=document.createElement("div");o.className="wan-drawer-overlay";document.body.appendChild(o)}return o}
function ensureDrawerHead(target,side){if(!target)return;let h=target.querySelector(":scope > .wan-drawer-head");if(!h){h=document.createElement("div");h.className="wan-drawer-head";h.innerHTML=`<div class="wan-drawer-head-title">${side==="left"?"List":"Page"}</div><button type="button" class="wan-drawer-close" aria-label="Close drawer">×</button>`;target.prepend(h)}}
function hasDrawerContent(target){return !!target&&Array.from(target.children).some(c=>!c.classList.contains("wan-drawer-head")&&!c.matches(".desktop-only"))}
function syncDrawerState(){const l=drawer("left"),r=drawer("right"),lb=document.querySelector(".wan-mobile-left-button"),rb=document.querySelector(".wan-mobile-right-button");if(lb){lb.hidden=!hasDrawerContent(l);lb.setAttribute("aria-expanded",l?.classList.contains("is-open")?"true":"false")}if(rb){rb.hidden=!hasDrawerContent(r);rb.setAttribute("aria-expanded",r?.classList.contains("is-open")?"true":"false")}if(!isMobile()){for(const d of[l,r]){if(!d)continue;try{d.inert=false}catch{}d.removeAttribute("aria-hidden")}return}for(const d of[l,r]){if(!d)continue;const hidden=!d.classList.contains("is-open");try{d.inert=hidden}catch{}d.setAttribute("aria-hidden",hidden?"true":"false")}}
function setOverlay(open){const o=ensureOverlay();o.style.removeProperty("opacity");o.classList.toggle("is-visible",open);document.body.classList.toggle("wan-drawer-open",open)}
function closeDrawers(immediate=false){for(const d of[drawer("left"),drawer("right")]){if(!d)continue;if(immediate)d.style.transition="none";d.style.removeProperty("transform");d.classList.remove("is-open");if(immediate){d.getBoundingClientRect();d.style.removeProperty("transition")}}setOverlay(false);syncDrawerState()}
function openDrawer(side){if(!isMobile())return;const d=drawer(side);if(!d||!hasDrawerContent(d))return;const other=drawer(side==="left"?"right":"left");if(other){other.style.removeProperty("transform");other.classList.remove("is-open")}d.classList.add("is-open");d.scrollTop=0;setOverlay(true);syncDrawerState()}
function bindSwipe(target,side){if(!target||target.dataset.wanSwipeBound==="true")return;target.dataset.wanSwipeBound="true";let active=false,h=false,sx=0,sy=0,st=0,dist=0;target.addEventListener("touchstart",e=>{if(!isMobile()||!target.classList.contains("is-open")||e.touches.length!==1)return;const t=e.touches[0];active=true;h=false;sx=t.clientX;sy=t.clientY;st=performance.now();dist=0},{passive:true});target.addEventListener("touchmove",e=>{if(!active||e.touches.length!==1)return;const t=e.touches[0],dx=t.clientX-sx,dy=t.clientY-sy,ax=Math.abs(dx),ay=Math.abs(dy);if(!h){if(ax<7&&ay<7)return;if(ay>ax){active=false;return}h=true}const dir=side==="left"?Math.max(0,-dx):Math.max(0,dx);if(dir<=0)return;e.preventDefault();const w=Math.max(1,target.getBoundingClientRect().width);dist=Math.min(w,dir);target.style.transition="none";target.style.transform=side==="left"?`translate3d(${-dist}px,0,0)`:`translate3d(${dist}px,0,0)`;ensureOverlay().style.opacity=String(.32*(1-Math.min(1,dist/w)))},{passive:false});const finish=cancel=>{const w=Math.max(1,target.getBoundingClientRect().width),v=dist/Math.max(1,performance.now()-st),close=!cancel&&h&&(dist>=DRAWER_DISTANCE||dist>=w*.2||v>=DRAWER_FLICK_VELOCITY);target.style.removeProperty("transition");target.style.removeProperty("transform");if(close){target.classList.remove("is-open");setOverlay(false);syncDrawerState()}else ensureOverlay().style.removeProperty("opacity");active=false;h=false;dist=0};target.addEventListener("touchend",()=>finish(false),{passive:true});target.addEventListener("touchcancel",()=>finish(true),{passive:true})}
function prepareDrawers(){const l=drawer("left"),r=drawer("right");ensureDrawerHead(l,"left");ensureDrawerHead(r,"right");bindSwipe(l,"left");bindSwipe(r,"right");syncDrawerState()}
function enhanceTagExplorer(){document.querySelectorAll(".tag-explorer-item").forEach(item=>{const tag=item.querySelector(":scope > .tag-explorer-tag"),notes=item.querySelector(":scope > .tag-explorer-notes");if(!tag||!notes)return;if(!item.querySelector(":scope > .wan-tag-toggle")){const b=document.createElement("button");b.type="button";b.className="wan-tag-toggle";b.textContent="›";b.setAttribute("aria-expanded","false");item.insertBefore(b,tag)}if(!item.querySelector(":scope > .wan-tag-route")){const a=document.createElement("a");a.className="wan-tag-route internal";a.href=tag.href;a.textContent="→";tag.insertAdjacentElement("afterend",a)}})}

function ensureGraphButton(){const g=drawer("right")?.querySelector(":scope > .graph");if(!g||g.querySelector(":scope > .wan-open-graph"))return;const b=document.createElement("button");b.type="button";b.className="wan-open-graph";b.textContent="Open Graph";const h=g.querySelector(":scope > h3");h?h.insertAdjacentElement("afterend",b):g.prepend(b)}
function ensureGraphModal(){let m=document.querySelector(".wan-mobile-graph-modal");if(!m){m=document.createElement("div");m.className="wan-mobile-graph-modal";m.innerHTML='<div class="wan-mobile-graph-head"><div class="wan-mobile-graph-title">Graph</div><button type="button" class="wan-mobile-graph-close" aria-label="Close graph">×</button></div><div class="wan-mobile-graph-stage"></div>';document.body.appendChild(m)}return m}
function restoreGraph(){const stage=document.querySelector(".wan-mobile-graph-stage"),outer=stage?.querySelector(":scope > .graph-outer"),ph=window.__wanMobileGraphPlaceholder;if(outer){if(ph?.isConnected&&ph.parentNode)ph.parentNode.insertBefore(outer,ph);else outer.remove()}if(ph?.isConnected)ph.remove();window.__wanMobileGraphPlaceholder=null}
function requestGraphRender(){requestAnimationFrame(()=>requestAnimationFrame(()=>document.dispatchEvent(new CustomEvent("render",{detail:{url:window.location.pathname}}))))}
function closeGraph(){restoreGraph();document.querySelector(".wan-mobile-graph-modal")?.classList.remove("is-open");document.body.classList.remove("wan-mobile-graph-open");requestGraphRender()}
function openGraph(){if(!isMobile())return;const g=drawer("right")?.querySelector(":scope > .graph"),outer=g?.querySelector(":scope > .graph-outer");if(!g||!outer)return;closeDrawers(true);const m=ensureGraphModal(),stage=m.querySelector(".wan-mobile-graph-stage");restoreGraph();const ph=document.createComment("wan-mobile-graph-placeholder");g.insertBefore(ph,outer);window.__wanMobileGraphPlaceholder=ph;stage.appendChild(outer);m.classList.add("is-open");document.body.classList.add("wan-mobile-graph-open");requestGraphRender()}

function formatDate(time){const visible=time?.textContent?.trim()||"",m=visible.match(/(\d{4}).*?(\d{1,2}).*?(\d{1,2})/);if(m)return`${m[1]}.${m[2].padStart(2,"0")}.${m[3].padStart(2,"0")}`;const raw=time?.getAttribute("datetime"),d=new Date(raw||"");if(Number.isNaN(d.getTime()))return visible;return`${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,"0")}.${String(d.getDate()).padStart(2,"0")}`}
function enhanceMobileTagRows(){const slug=document.body?.dataset?.slug||"";if(!slug.startsWith("tags/")||slug==="tags/index")return;document.querySelectorAll(".center .page-listing .section-li > .section").forEach(section=>{section.querySelector(":scope > .wan-mobile-tag-meta")?.remove();const time=section.querySelector(":scope > .meta time"),tags=Array.from(section.querySelectorAll(":scope > .tags > li > a.tag-link"));if(!time&&!tags.length)return;const line=document.createElement("div");line.className="wan-mobile-tag-meta";let has=false;if(time){const t=document.createElement("time");t.textContent=formatDate(time);line.appendChild(t);has=true}for(const tag of tags){if(has){const s=document.createElement("span");s.className="wan-mobile-tag-separator";s.textContent="·";line.appendChild(s)}line.appendChild(tag.cloneNode(true));has=true}const desc=section.querySelector(":scope > .desc");desc?desc.insertAdjacentElement("afterend",line):section.appendChild(line)})}
function itemTitle(item){return item.querySelector(".desc h3 a")?.textContent?.trim()||item.querySelector("h3 a")?.textContent?.trim()||""}
function itemModifiedAt(item){const ts=Date.parse(item.querySelector(".meta time")?.getAttribute("datetime")||"");return Number.isFinite(ts)?ts:0}
function addRecentMarker(item,modifiedAt){const h=item.querySelector(".desc h3")||item.querySelector("h3");if(!h)return;h.querySelector(":scope > .wan-recent-marker")?.remove();const age=Date.now()-modifiedAt;if(!modifiedAt||age<0||age>STATE_TTL_MS)return;const s=document.createElement("sup");s.className="wan-recent-marker";s.textContent="*";s.tabIndex=0;s.setAttribute("aria-label","New or updated within 24 hours");h.appendChild(s)}
function tagStateKey(slug){return`${TAG_STATE_PREFIX}${slug}`}
function loadSort(){const saved=safeRead(SORT_STATE_KEY),sort=["az","za","newest","oldest"].includes(saved?.sort)?saved.sort:"az";safeWrite(SORT_STATE_KEY,{sort});return sort}
function loadTagState(slug){const saved=safeRead(tagStateKey(slug)),state={query:typeof saved?.query==="string"?saved.query:"",page:Number.isInteger(saved?.page)&&saved.page>0?saved.page:1};safeWrite(tagStateKey(slug),state);return state}

function buildTagControls(listing,list,records,slug){
  listing.querySelector(":scope > .tag-page-controls")?.remove();listing.querySelector(":scope > .wan-tag-toolbar")?.remove();listing.querySelector(":scope > .wan-tag-pagination")?.remove();
  list.style.removeProperty("height");list.style.removeProperty("min-height");listing.dataset.enhanced="true";
  const listHost=list.parentElement||list;
  let sort=loadSort();const restored=loadTagState(slug);let query=restored.query,page=restored.page;
  const toolbar=document.createElement("div");toolbar.className="wan-tag-toolbar";const search=document.createElement("input");search.type="search";search.className="wan-tag-search";search.placeholder="Search title";search.value=query;const select=document.createElement("select");select.className="wan-tag-sort";select.setAttribute("aria-label","Sort pages");for(const[v,l]of[["az","A–Z"],["za","Z–A"],["newest","Newest"],["oldest","Oldest"]]){const o=document.createElement("option");o.value=v;o.textContent=l;select.appendChild(o)}select.value=sort;toolbar.append(search,select);
  const pagination=document.createElement("div");pagination.className="wan-tag-pagination";const left=document.createElement("div");left.className="wan-tag-nav-side is-left";const right=document.createElement("div");right.className="wan-tag-nav-side is-right";const nums=document.createElement("div");nums.className="wan-tag-page-numbers";const prev=document.createElement("button");prev.className="wan-tag-prev";prev.textContent="‹ Previous";const next=document.createElement("button");next.className="wan-tag-next";next.textContent="Next ›";left.appendChild(prev);right.appendChild(next);pagination.append(left,nums,right);
  listing.insertBefore(toolbar,listHost);listHost.insertAdjacentElement("afterend",pagination);
  const save=()=>{safeWrite(SORT_STATE_KEY,{sort});safeWrite(tagStateKey(slug),{query,page})};
  const filtered=()=>{const needle=query.toLocaleLowerCase().replace(/\s+/g," ").trim();const arr=needle?records.filter(r=>r.title.toLocaleLowerCase().replace(/\s+/g," ").trim().includes(needle)):[...records];arr.sort((a,b)=>{if(sort==="newest"||sort==="oldest"){const d=a.modifiedAt-b.modifiedAt;if(d!==0)return sort==="newest"?-d:d}const d=titleCollator.compare(a.title,b.title);return sort==="za"?-d:d});return arr};
  const render=()=>{const arr=filtered(),pages=Math.max(1,Math.ceil(arr.length/TAG_PAGE_SIZE));page=Math.min(Math.max(1,page),pages);save();records.forEach(r=>r.item.hidden=true);arr.forEach(r=>list.appendChild(r.item));arr.slice((page-1)*TAG_PAGE_SIZE,page*TAG_PAGE_SIZE).forEach(r=>r.item.hidden=false);pagination.classList.toggle("is-hidden",arr.length<=TAG_PAGE_SIZE);prev.disabled=page<=1;next.disabled=page>=pages;nums.replaceChildren();for(let i=1;i<=pages;i++){const b=document.createElement("button");b.className=`wan-tag-page-number${i===page?" is-active":""}`;b.textContent=String(i);if(i===page)b.setAttribute("aria-current","page");b.addEventListener("click",()=>{page=i;render()});nums.appendChild(b)}};
  search.addEventListener("input",()=>{query=search.value;page=1;render()});select.addEventListener("change",()=>{sort=select.value;page=1;render()});prev.addEventListener("click",()=>{if(page>1){page--;render()}});next.addEventListener("click",()=>{page++;render()});render();
}

function enhanceTagPage(){const slug=document.body?.dataset?.slug||"";if(!slug.startsWith("tags/")||slug==="tags/index")return;const listing=document.querySelector(".center .page-listing");const list=listing?.querySelector(".section-ul");if(!listing||!list)return;const items=Array.from(list.querySelectorAll(":scope > .section-li"));if(!items.length)return;const records=items.map(item=>{const r={item,title:itemTitle(item),modifiedAt:itemModifiedAt(item)};addRecentMarker(item,r.modifiedAt);return r});buildTagControls(listing,list,records,slug)}

function resetForNavigation(){restoreGraph();document.querySelector(".wan-mobile-graph-modal")?.classList.remove("is-open");document.body.classList.remove("wan-mobile-graph-open");closeDrawers(true)}
function apply(){ensureStyles();resetForNavigation();ensureHeader();ensureOverlay();prepareDrawers();enhanceTagExplorer();ensureGraphButton();ensureGraphModal();enhanceMobileTagRows();enhanceTagPage();syncDrawerState()}
function installHandlers(){if(window.__wanMobileUiHandlersInstalled)return;window.__wanMobileUiHandlersInstalled=true;document.addEventListener("click",e=>{if(!isMobile())return;const t=e.target instanceof Element?e.target:null;if(!t)return;if(t.closest(".wan-mobile-left-button")){e.preventDefault();openDrawer("left");return}if(t.closest(".wan-mobile-right-button")){e.preventDefault();openDrawer("right");return}if(t.closest(".wan-mobile-header-title")){e.preventDefault();window.scrollTo({top:0,behavior:"smooth"});return}if(t.closest(".wan-drawer-overlay,.wan-drawer-close")){e.preventDefault();closeDrawers();return}const toggle=t.closest(".wan-tag-toggle");if(toggle){e.preventDefault();const item=toggle.closest(".tag-explorer-item");const expanded=item?.classList.toggle("is-expanded");toggle.setAttribute("aria-expanded",expanded?"true":"false");return}if(t.closest(".wan-open-graph")){e.preventDefault();openGraph();return}if(t.closest(".wan-mobile-graph-close")){e.preventDefault();closeGraph();return}if(t.closest(".sidebar.left a,.sidebar.right .toc a,.sidebar.right .backlinks a"))closeDrawers()});window.addEventListener("resize",()=>{if(!isMobile()){closeDrawers(true);if(document.querySelector(".wan-mobile-graph-modal.is-open"))closeGraph()}syncDrawerState()},{passive:true});window.addEventListener("pageshow",()=>setTimeout(apply,0))}

ensureStyles();installHandlers();if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",apply,{once:true});else apply();document.addEventListener("nav",apply,true)
